-- Migration do modulo Produtos (Etapa 7B1 - base backend, sem controller/endpoint ainda).
--
-- Cria a tabela minima de produtos fisicos (ver docs/modules/produtos.md).
-- Isolamento por empresa conforme DEC-016: todo produto pertence a uma
-- empresa e nunca deve ser lido/alterado fora dela.
--
-- Padrao de chave primaria interna: BIGINT GENERATED BY DEFAULT AS IDENTITY (DEC-015).
-- Timestamps em TIMESTAMP sem timezone, mesmo padrao de empresa/usuario (V2).

CREATE TABLE produtos (
    id              BIGINT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    empresa_id      BIGINT         NOT NULL,
    nome            VARCHAR(150)   NOT NULL,
    categoria       VARCHAR(100),
    unidade         VARCHAR(20),
    preco_venda     NUMERIC(12,2)  NOT NULL,
    custo           NUMERIC(12,2),
    -- NUMERIC(12,3): 3 casas decimais para suportar unidades fracionarias
    -- (ex.: kg, litro) no estoque minimo. Decisao padrao para o modulo.
    estoque_minimo  NUMERIC(12,3),
    codigo_barras   VARCHAR(50),
    sku             VARCHAR(50),
    ativo           BOOLEAN        NOT NULL DEFAULT true,
    criado_em       TIMESTAMP      NOT NULL DEFAULT now(),
    atualizado_em   TIMESTAMP,
    CONSTRAINT fk_produto_empresa FOREIGN KEY (empresa_id) REFERENCES empresa (id),
    CONSTRAINT ck_produto_preco_venda_nao_negativo CHECK (preco_venda >= 0),
    CONSTRAINT ck_produto_custo_nao_negativo CHECK (custo IS NULL OR custo >= 0),
    CONSTRAINT ck_produto_estoque_minimo_nao_negativo CHECK (estoque_minimo IS NULL OR estoque_minimo >= 0),
    -- Unicidade de SKU e codigo de barras por empresa, apenas quando informados.
    -- No Postgres, UNIQUE trata multiplos valores NULL como nao-conflitantes
    -- (comportamento padrao SQL), entao uma constraint simples ja garante que
    -- produtos sem SKU/codigo de barras nao colidam entre si.
    CONSTRAINT uq_produto_empresa_sku UNIQUE (empresa_id, sku),
    CONSTRAINT uq_produto_empresa_codigo_barras UNIQUE (empresa_id, codigo_barras)
);

-- Indice para acelerar o lookup por empresa (mesmo padrao de idx_usuario_empresa).
CREATE INDEX idx_produto_empresa ON produtos (empresa_id);
